import java.util.List;
import java.util.concurrent.ThreadLocalRandom;

@Service
public class OrderService {

    private static final String PRODUCT_STATUS_ACTIVE = "ACTIVE";
    private static final String ORDER_STATUS_PENDING = "PENDING";
    private static final String ORDER_STATUS_CANCELLED = "CANCELLED";
    private static final String ROLE_ADMIN = "ADMIN";
    private static final DateTimeFormatter ORDER_NO_TIME_FORMAT =
            DateTimeFormatter.ofPattern("yyyyMMddHHmmss");

    private final OrderMapper orderMapper;
    private final ProductMapper productMapper;
    private final AuditLogService auditLogService;

    public OrderService(OrderMapper orderMapper, ProductMapper productMapper,
                        AuditLogService auditLogService) {
        this.orderMapper = orderMapper;
        this.productMapper = productMapper;
        this.auditLogService = auditLogService;
    }

    public Order createOrder(Long userId, Long productId, Integer duration,
                             Integer quantity) {
        Product product = productMapper.findById(productId);
        if (product == null || !PRODUCT_STATUS_ACTIVE.equals(product.getStatus())) {
            throw new IllegalArgumentException("产品不存在或已下线");
        }
        if (duration == null || duration < 1) {
            throw new IllegalArgumentException("订购时长不合法");
        }
        int effectiveQuantity = (quantity == null || quantity < 1) ? 1 : quantity;

        BigDecimal totalPrice = product.getPricePerMonth()
                .multiply(BigDecimal.valueOf(duration))
                .multiply(BigDecimal.valueOf(effectiveQuantity));

        LocalDateTime now = LocalDateTime.now();
        Order order = new Order();
        order.setOrderNo(generateOrderNo(now));
        order.setUserId(userId);
        order.setProductId(productId);
        order.setDurationMonths(duration);
        order.setQuantity(effectiveQuantity);
        order.setTotalPrice(totalPrice);
        order.setStatus(ORDER_STATUS_PENDING);
        order.setCreatedAt(now);
        order.setExpireAt(now.plusMonths(duration));

        orderMapper.insert(order);

        auditLogService.log(userId, "CREATE_ORDER", "ORDER", order.getOrderNo(), "创建订单");

        return order;
